-- PT118-S4-Q23. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT118-S4-Q23$batch13$ AND q.stimulus=$batch13$Agricultural economist: Over the past several years, increases in worldwide grain production have virtually ceased. Further increases will be extremely difficult; most usable farmland is already being farmed with near-maximal efficiency. But worldwide demand for grain has been increasing steadily, due largely to continuing population growth. Hence, a severe worldwide grain shortage is likely.$batch13$ AND q.prompt=$batch13$Which one of the following most accurately describes the role played in the agricultural economist's argument by the claim that further increases in worldwide grain production will be extremely difficult?$batch13$ AND q.correct_choice=$batch13$E$batch13$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT118-S4-Q23$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT118-S4-Q23$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$A severe worldwide grain shortage is likely.$batch13$), (1, $batch13$Intermediate Conclusion$batch13$, $batch13$Further increases in worldwide grain production will be extremely difficult.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$Most usable farmland is already farmed at near-maximal efficiency. Production increases have virtually stopped. Demand keeps rising, largely because of population growth.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$The semicolon links the named claim to its reason: the farmland is already near its limit. Then "Hence" draws the shortage conclusion. Supply can't grow and demand keeps growing. The claim is supported and supports the conclusion, so it's an intermediate conclusion.$batch13$), (4, $batch13$Goal$batch13$, $batch13$An intermediate conclusion offered as support for the main conclusion.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT118-S4-Q23$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$It isn't a separate conclusion. It supports the shortage prediction.$batch13$), ($batch13$B$batch13$, $batch13$The conclusion predicts a shortage. It doesn't explain what causes this claim.$batch13$), ($batch13$C$batch13$, $batch13$It isn't the only premise. Rising demand is just as necessary for a shortage.$batch13$), ($batch13$D$batch13$, $batch13$This is the most popular trap. The claim is a prediction, but its support is the farmland point after the semicolon, not the first claim about production stalling.$batch13$), ($batch13$E$batch13$, $batch13$The farmland point supports it, and it supports the shortage conclusion.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT118-S4-Q23$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
